<?php
declare(strict_types=1);

function marketing_phase3_add_column(string $table,string $column,string $definition):void{
 if(!marketing_column_exists($table,$column))db()->exec("ALTER TABLE `$table` ADD COLUMN `$column` $definition");
}
function marketing_phase3_index_exists(string $table,string $index):bool{
 $q=db()->prepare('SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND INDEX_NAME=?');$q->execute([$table,$index]);return(int)$q->fetchColumn()>0;
}
function marketing_phase3_add_index(string $table,string $index,string $columns):void{
 if(!marketing_phase3_index_exists($table,$index))db()->exec("ALTER TABLE `$table` ADD INDEX `$index` ($columns)");
}
