function marketing_phase3_objectives():array{return['Awareness','Engagement','Traffic','Sales','Product Launch','Promotion','New Arrival','Education','Retention','Other'];}
function marketing_phase3_campaign_statuses():array{return['draft','planned','active','paused','completed','cancelled'];}
function marketing_phase3_ad_statuses():array{return['draft','ready_for_review','changes_requested','approved','rejected','running','paused','completed','cancelled'];}
function marketing_phase3_sources():array{return['manual'=>'Manual','portal_orders'=>'Portal Orders','woocommerce'=>'WooCommerce','meta_import'=>'Meta Import','whatsapp_manual'=>'WhatsApp Manual','newsletter_import'=>'Newsletter Import','future_api'=>'Future API'];}
function marketing_phase3_audit(string $action,string $entityType,int $entityId,string $details=''):void{
 $u=current_user();db()->prepare('INSERT INTO marketing_audit_log(action,entity_type,entity_id,details,actor_id,actor_name)VALUES(?,?,?,?,?,?)')->execute([$action,$entityType,$entityId,$details?:null,(int)$u['id'],(string)$u['name']]);
}
function marketing_phase3_campaign_code(string $name,string $startDate):string{
 $slug=strtoupper(trim(preg_replace('/[^A-Za-z0-9]+/','-',$name),'-'));$slug=substr($slug?:'CAMPAIGN',0,48);$stamp=$startDate?strtoupper(date('M-Y',strtotime($startDate))):date('M-Y');return $stamp.'-'.$slug;
}
function marketing_phase3_period(array $input):array{
 $today=new DateTimeImmutable('today');$key=(string)($input['period']??'this_month');
 if($key==='today'){$from=$today;$to=$today;$label='Today';}
 elseif($key==='last_7_days'){$from=$today->modify('-6 days');$to=$today;$label='Last 7 Days';}
 elseif($key==='last_30_days'){$from=$today->modify('-29 days');$to=$today;$label='Last 30 Days';}
 elseif($key==='last_month'){$from=$today->modify('first day of last month');$to=$today->modify('last day of last month');$label='Last Month';}
 elseif($key==='custom'){$fromRaw=(string)($input['date_from']??'');$toRaw=(string)($input['date_to']??'');$from=$fromRaw?new DateTimeImmutable($fromRaw):$today->modify('first day of this month');$to=$toRaw?new DateTimeImmutable($toRaw):$today;$label='Custom Range';}
 else{$key='this_month';$from=$today->modify('first day of this month');$to=$today;$label='This Month';}
 if($from>$to)[$from,$to]=[$to,$from];return['key'=>$key,'from'=>$from->format('Y-m-d'),'to'=>$to->format('Y-m-d'),'label'=>$label];
}
function marketing_phase3_allowed_campaign(int $campaignId):?array{
 if($campaignId<1)return null;$params=[$campaignId];$where='c.id=?';if(!marketing_is_owner()){$where.=' AND c.assigned_employee_id=?';$params[]=marketing_employee_id();}$q=db()->prepare("SELECT c.* FROM marketing_campaigns c WHERE $where LIMIT 1");$q->execute($params);return$q->fetch()?:null;
}
function marketing_phase3_upload_evidence(array $file):array{
